363	/** 生成每日一句话总结 */
364	function generateDailySummary(state, startCash, startHealth, startHappiness) {
365	  var cash = state.resources.cash || 0;
366	  var bank = state.resources.bankBalance || 0;
367	  var delta = cash - startCash;
368	  var healthDrop = startHealth - ((state.status && state.status.health) || 100);
369	  var happyDrop =
370	    startHappiness - ((state.needs && state.needs.happiness) || 0);
371	
372	  var highlights = [];
373	
374	  // 财务总结
375	  if (delta >= 500) {
376	    highlights.push("今天大丰收，净赚了¥" + delta.toLocaleString());
377	  } else if (delta >= 100) {
378	    highlights.push("今天赚了¥" + delta.toLocaleString() + "，小有收获");
379	  } else if (delta >= 0) {
380	    highlights.push("今天收支基本持平");
381	  } else if (delta < -200) {
382	    highlights.push(
383	      "今天支出比收入多了¥" + Math.abs(delta).toLocaleString() + "，要节省一点",
384	    );
385	  } else {
386	    highlights.push("今天支出略多于收入");
387	  }
388	
389	  // 健康/状态提示
390	  if (healthDrop >= 10) {
391	    highlights.push("健康下降了不少");
392	  }
393	  if (happyDrop >= 15) {
394	    highlights.push("心情差了很多，注意调整");
395	  }
396	
397	  // 银行存款有利息
398	  if (bank > 0) {
399	    highlights.push("银行里的¥" + bank.toLocaleString() + "还在生息");
400	  }
401	
402	  // 节日
403	  if (typeof getCurrentFestival === "function") {
404	    var fest = getCurrentFestival(state.player.day);
405	    if (fest) highlights.push(fest.icon + " " + fest.name + "气氛浓厚");
406	  }
407	
408	  var summary = highlights.slice(0, 2).join("，") + "。";
409	  return "📋 今日总结：" + summary;
410	}
411	
412	/**
413	 * 执行每日结算管线。
414	 * 遍历所有步骤，遇到极端状态('skip_day')时短路。
415	 * MiniMax 友好：新增步骤只需 push 一个 {name, fn} 对象。
416	 */
417	function runDailyPipeline(state) {
418	  // 记录日始状态用于今日总结（存入 state.flags 供 end_log fn 读取）
419	  state.flags._dayStartCash = state.resources.cash || 0;
420	  state.flags._dayStartHealth = (state.status && state.status.health) || 100;
421	  state.flags._dayStartHappiness = (state.needs && state.needs.happiness) || 0;
422	
423	  for (var i = 0; i < DAILY_PIPELINE.length; i++) {
424	    var step = DAILY_PIPELINE[i];
425	
426	    // 极端状态短路逻辑：
427	    // extreme_check 步骤返回 'skip_day' 时，跳过后续非核心步骤
428	    // 但 finance / autosave 始终执行（保证利息和存档不丢）
429	    if (step.name === "extreme_check") {
430	      var result = step.fn(state);
431	      if (result === "skip_day") {
432	        StateManager.addMessage(
433	          "🌙 第" + state.player.day + "天在昏迷中过去了...",
434	          "danger",
435	        );
436	        // 执行最后的核心步骤：财务、存档
437	        for (var j = i + 1; j < DAILY_PIPELINE.length; j++) {
438	          var lateStep = DAILY_PIPELINE[j];
439	          if (lateStep.name === "finance" || lateStep.name === "autosave") {
440	            lateStep.fn(state);
441	          }
442	        }
443	        return; // 短路
444	      }
445	    } else {
446	      step.fn(state);
447	    }
448	  }
449	}
450	
451	/**
452	 * endDay — 仅保留管线调度逻辑（MiniMax 友好：170行→8行）
453	 */
454	function endDay() {
455	  var state = StateManager.getState();
456	  runDailyPipeline(state);
457	}
